// @spec specs/hal-engine-tool-input-validation/spec.md#7
import {expect, it} from '@jest/globals';
import {ToolRegistry} from './registry.js';

it('executes a registered tool with a valid location', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather forecast',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async input => JSON.stringify(input)
  );

  expect(await registry.execute('weather', {location: 'Berlin'})).toEqual({result: '{\"location\":\"Berlin\"}'});
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.import.test.ts --runInBand"
